#!/usr/bin/env node
/**
 * Build lib/ with DeepSeek Harness's own toolchain.
 *
 * The plugin's Remote API code is generated by DSH's Typert generator and its
 * browser half must use DSH's client bundle format, so the build runs inside a
 * DSH source checkout: this script copies the plugin into
 * <checkout>/packages/community/archive-cleanup, builds it there, and copies
 * the result back into lib/.
 *
 * Usage: node scripts/build.mjs <path-to-deepseek-harness-checkout>
 * The checkout must already be installed and built (`pnpm install && pnpm run build`).
 */
import { execSync } from 'node:child_process'
import { cpSync, existsSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { basename, join, resolve, sep } from 'node:path'

const PNPM = 'npx -y pnpm@11.28.5'
const PACKAGE_DIR = 'packages/community/archive-cleanup'
const SOURCES = ['src', 'tests', 'locale', 'cordis.patch.yml', 'tsconfig.host.json', 'tsconfig.client.json', 'tsdown.config.ts']
/** DSH packages the sources import, only for type checking and bundling inside the checkout. */
const DSH_DEV_DEPENDENCIES = [
  '@deepseek-ai/cordis',
  '@deepseek-ai/dsh-api-gateway',
  '@deepseek-ai/dsh-api-remotes',
  '@deepseek-ai/dsh-api-session-controller',
  '@deepseek-ai/dsh-api-workspace-controller',
  '@deepseek-ai/dsh-client-connection',
  '@deepseek-ai/dsh-client-locale',
  '@deepseek-ai/dsh-client-store',
  '@deepseek-ai/dsh-client-ui-layout',
  '@deepseek-ai/dsh-client-ui-primitives',
  '@deepseek-ai/dsh-client-ui-renderer',
  '@deepseek-ai/dsh-client-ui-session',
  '@deepseek-ai/dsh-client-ui-settings',
  '@deepseek-ai/dsh-client-ui-slots',
  '@deepseek-ai/dsh-client-ui-workspace',
  '@deepseek-ai/dsh-home-paths',
  '@deepseek-ai/dsh-session',
  '@deepseek-ai/dsh-session-persistence',
  '@deepseek-ai/dsh-storage-domain',
  '@deepseek-ai/dsh-typert-protocol',
  '@deepseek-ai/dsh-workspace',
]

const root = resolve(import.meta.dirname, '..')
const checkout = resolve(process.argv[2] ?? process.env.DSH_SRC ?? '.')
if (!existsSync(join(checkout, 'tsconfig.host.json')) || !existsSync(join(checkout, 'packages'))) {
  console.error('usage: node scripts/build.mjs <path-to-deepseek-harness-checkout>')
  process.exit(2)
}
const target = join(checkout, PACKAGE_DIR)

const run = (command, cwd = checkout, env = {}) => {
  console.log(`> ${command}`)
  execSync(command, { cwd, stdio: 'inherit', env: { ...process.env, ...env } })
}

/** Point a DSH workspace range at every DSH package so pnpm links the checkout's copies. */
const workspaceRange = name => (name === '@deepseek-ai/cordis' ? 'workspace:~' : 'workspace:*')

/** Insert one project reference into a DSH aggregate tsconfig (JSON with comments) unless present. */
function addReference(file, path) {
  const text = readFileSync(join(checkout, file), 'utf8')
  if (text.includes(`"${path}"`)) return
  const anchor = '"references": ['
  if (!text.includes(anchor)) throw new Error(`no "references" list in ${file}`)
  writeFileSync(join(checkout, file), text.replace(anchor, `${anchor}\n    { "path": "${path}" },`))
}

// 1. Copy the plugin into the checkout.
for (const name of SOURCES) {
  rmSync(join(target, name), { recursive: true, force: true })
  cpSync(join(root, name), join(target, name), { recursive: true })
}
const manifest = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'))
manifest.peerDependencies = Object.fromEntries(Object.keys(manifest.peerDependencies).map(name => [name, workspaceRange(name)]))
manifest.devDependencies = Object.fromEntries([
  ...DSH_DEV_DEPENDENCIES.map(name => [name, workspaceRange(name)]),
  ['react', '^18.2.0'],
  ['react-dom', '^18.2.0'],
])
writeFileSync(join(target, 'package.json'), JSON.stringify(manifest, null, 2) + '\n')
// The solution tsconfig lives only in the checkout, so tests run outside it never load DSH's base configs.
writeFileSync(join(target, 'tsconfig.json'), JSON.stringify({
  files: [],
  references: [{ path: './tsconfig.host.json' }, { path: './tsconfig.client.json' }],
}, null, 2) + '\n')
addReference('tsconfig.host.json', `./${PACKAGE_DIR}/tsconfig.host.json`)
addReference('tsconfig.client.json', `./${PACKAGE_DIR}/tsconfig.client.json`)

// 2. Build with DSH's toolchain, from a clean lib/.
rmSync(join(target, 'lib'), { recursive: true, force: true })
run(`${PNPM} install`)
run('npx tsx scripts/generate-typert.ts')
run(`node ./node_modules/typescript/bin/tsc -b ${PACKAGE_DIR}/tsconfig.host.json ${PACKAGE_DIR}/tsconfig.client.json`)
run('npx tsdown --config-loader native', target, { DSH_BUILD_FACE: 'client' })

// 3. Copy the publishable output back.
rmSync(join(root, 'lib'), { recursive: true, force: true })
cpSync(join(target, 'lib'), join(root, 'lib'), {
  recursive: true,
  filter: source => !source.endsWith('.map') && !source.endsWith('.tsbuildinfo')
    && !(source.includes(`${join('lib', 'types')}`) && source.endsWith('.js') && basename(source) !== 'types.js'),
})
// Bundlers leave the build machine's absolute path in region comments; keep it out of published files.
for (const file of ['index.js', 'client.js']) {
  const path = join(root, 'lib', file)
  writeFileSync(path, readFileSync(path, 'utf8').replaceAll(target + sep, '').replaceAll(target.replaceAll(sep, '/') + '/', ''))
}
console.log(`built ${join(root, 'lib')}`)
